import {brushes,settings,strokeMarkup,previewPoints} from './drawing.js';
export const palette=[['Ink','#292536'],['Slate','#68738a'],['White','#ffffff'],['Red','#e34a59'],['Orange','#ec8b35'],['Green','#259b73'],['Blue','#3278e4'],['Purple','#794de8']];
export function drawingControls(values,disabled=false){
 const s=settings(values),editingObject=values?.type==='pen',renderStyle={...s,perfectStroke:Boolean(editingObject&&s.perfectStroke)},off=disabled?'disabled':'',smoothOff=editingObject&&s.perfectStroke||disabled?'disabled':'';
 const perfectControl=editingObject
  ?`<div class="perfect-stroke shift-shape-status"><span><b>${s.perfectStroke?'Perfect shape':'Freehand stroke'}</b><small>${s.perfectStroke?'Created while Shift was held.':'This stroke stays freehand. Hold Shift while creating a new stroke to recognize a shape.'}</small></span></div>`
  :`<label class="perfect-stroke"><input data-draw-prop="perfectStroke" type="checkbox" role="switch" ${s.perfectStroke?'checked':''} ${off}><span><b>Shift shape recognition</b><small>When enabled, hold Shift while drawing to create a clean line, ellipse, or curve. Normal strokes stay freehand.</small></span></label>`;
 return `<div class="draw-settings"><div class="draw-label">Brush</div><div class="brush-grid" role="group" aria-label="Brush">${brushes.map(brush=>`<button class="brush-option ${s.brush===brush.id?'chosen':''}" data-brush="${brush.id}" aria-pressed="${s.brush===brush.id}" ${off}><svg viewBox="0 0 216 64" aria-hidden="true">${strokeMarkup(previewPoints,{...renderStyle,brush:brush.id,stroke:brush.id==='pencil'?3:brush.id==='fineliner'?2.5:6})}</svg><span>${brush.name}</span><small>${brush.description}</small></button>`).join('')}</div><div class="draw-label">Color</div><div class="color-picker-row"><div class="color-wheel" data-color-wheel role="slider" tabindex="0" aria-label="Brush hue" style="--current:${s.color}"><span></span></div><label class="color-hex"><span>Exact color</span><input data-draw-prop="color" type="color" value="${s.color}" ${off}></label></div><div class="color-palette" role="group" aria-label="Drawing color">${palette.map(([name,color])=>`<button class="color-swatch ${s.color.toLowerCase()===color?'chosen':''}" data-draw-color="${color}" aria-label="${name}" aria-pressed="${s.color.toLowerCase()===color}" title="${name}" style="--swatch:${color}" ${off}></button>`).join('')}</div><div class="draw-range"><label for="draw-width">Width</label><output id="draw-width-value" for="draw-width">${s.stroke} px</output><input id="draw-width" data-draw-prop="stroke" type="range" min="1" max="30" step=".5" value="${s.stroke}" ${off}></div><div class="draw-range"><label for="draw-opacity">Opacity</label><output id="draw-opacity-value" for="draw-opacity">${s.opacity}%</output><input id="draw-opacity" data-draw-prop="opacity" type="range" min="1" max="100" step="1" value="${s.opacity}" ${off}></div>${s.brush==='pencil'?`<div class="draw-range pencil-texture"><label for="draw-pencil-texture">Graphite grain</label><output id="draw-pencil-texture-value" for="draw-pencil-texture">${s.pencilTexture}%</output><input id="draw-pencil-texture" data-draw-prop="pencilTexture" type="range" min="0" max="100" step="1" value="${s.pencilTexture}" ${off}><div class="range-extremes"><span>Clean</span><span>Sketchy</span></div></div>`:''}<div class="draw-label">Stroke correction</div><label class="perfect-stroke smooth-stroke"><input data-draw-prop="smoothStroke" type="checkbox" role="switch" ${s.smoothStroke?'checked':''} ${smoothOff}><span><b>Stroke smoothing</b><small>Steady every brush without turning it into a shape.</small></span></label>${s.smoothStroke?`<div class="smooth-controls ${editingObject&&s.perfectStroke?'disabled-range':''}"><div class="draw-range primary-smoothing"><label for="draw-streamline">StreamLine</label><output id="draw-streamline-value" for="draw-streamline">${s.streamline}</output><input id="draw-streamline" data-draw-prop="streamline" type="range" min="0" max="100" step="1" value="${s.streamline}" ${smoothOff}><div class="range-extremes"><span>Natural</span><span>Controlled</span></div></div><details class="advanced-smoothing"><summary>Advanced stabilization</summary><p>Fine-tune the stroke engine when StreamLine alone is not enough.</p><div class="draw-range"><label for="draw-smooth-quality">Quality</label><output id="draw-smooth-quality-value" for="draw-smooth-quality">${s.smoothQuality}</output><input id="draw-smooth-quality" data-draw-prop="smoothQuality" type="range" min="1" max="100" step="1" value="${s.smoothQuality}" ${smoothOff}><div class="range-extremes"><span>Fast</span><span>Refined</span></div></div><div class="draw-range"><label for="draw-smooth-weight">Weight</label><output id="draw-smooth-weight-value" for="draw-smooth-weight">${s.smoothWeight}</output><input id="draw-smooth-weight" data-draw-prop="smoothWeight" type="range" min="1" max="100" step="1" value="${s.smoothWeight}" ${smoothOff}><div class="range-extremes"><span>Responsive</span><span>Rigid</span></div></div><div class="draw-range"><label for="draw-stabilization">Stabilization</label><output id="draw-stabilization-value" for="draw-stabilization">${s.stabilization}</output><input id="draw-stabilization" data-draw-prop="stabilization" type="range" min="0" max="100" step="1" value="${s.stabilization}" ${smoothOff}><div class="range-extremes"><span>Agile</span><span>Straight</span></div></div><div class="draw-range"><label for="draw-motion-filtering">Motion filtering</label><output id="draw-motion-filtering-value" for="draw-motion-filtering">${s.motionFiltering}</output><input id="draw-motion-filtering" data-draw-prop="motionFiltering" type="range" min="0" max="100" step="1" value="${s.motionFiltering}" ${smoothOff}><div class="range-extremes"><span>Detailed</span><span>Clean</span></div></div><div class="draw-range"><label for="draw-motion-expression">Expression</label><output id="draw-motion-expression-value" for="draw-motion-expression">${s.motionExpression}</output><input id="draw-motion-expression" data-draw-prop="motionExpression" type="range" min="0" max="100" step="1" value="${s.motionExpression}" ${smoothOff}><div class="range-extremes"><span>Precise</span><span>Expressive</span></div></div><div class="draw-range"><label for="draw-pressure-smoothing">Pressure smoothing</label><output id="draw-pressure-smoothing-value" for="draw-pressure-smoothing">${s.pressureSmoothing}</output><input id="draw-pressure-smoothing" data-draw-prop="pressureSmoothing" type="range" min="0" max="100" step="1" value="${s.pressureSmoothing}" ${smoothOff}><div class="range-extremes"><span>Direct</span><span>Even</span></div></div><label class="perfect-stroke tip-attachment"><input data-draw-prop="tipAttachment" type="checkbox" role="switch" ${s.tipAttachment?'checked':''} ${smoothOff}><span><b>Attach first point</b><small>Start exactly where the pen first touches the canvas.</small></span></label></details></div>`:''}${perfectControl}<label class="perfect-stroke dynamics-switch"><input data-draw-prop="pressureDynamics" type="checkbox" role="switch" ${s.pressureDynamics?'checked':''} ${off}><span><b>Pressure dynamics</b><small>Use stylus pressure—or mouse speed—for expressive brush width.</small></span></label><div class="stroke-preview"><svg id="draw-preview" viewBox="0 0 216 64" aria-label="Current brush stroke preview">${strokeMarkup(previewPoints,renderStyle)}</svg></div><p class="draw-description">Draw normally for freehand. Hold Shift while drawing for shape recognition. Alt-click continues from the previous stroke with a straight segment.</p></div>`;
}
